import React, { useState, useEffect } from 'react';
import { 
  Card, 
  Typography, 
  Avatar, 
  Switch, 
  Button, 
  Modal, 
  Tag,
  Space,
  Divider,
  Badge,
  Tooltip,
  Alert
} from 'antd';
import { 
  FileTextOutlined, 
  StarOutlined, 
  CrownOutlined,
  InfoCircleOutlined,
  UserOutlined,
  RobotOutlined
} from '@ant-design/icons';

const { Title, Text, Paragraph } = Typography;

// Типы
interface Prompt {
  id: number;
  name: string;
  description: string;
  category: string;
  is_active: boolean;
  is_base: boolean;
  can_work_alone?: boolean; // Может работать без базовой личности
  memory_algorithm?: string; // JSON конфигурация внутренних алгоритмов памяти
  icon_color?: string;
  icon_emoji?: string;
  locale?: string;
  key?: string;
  features?: string; // JSON строка с функциями
  target_audience?: string; // Описание целевой аудитории
  activation_triggers?: string; // JSON строка с триггерами
  kind?: string; // 'therapeutic' | 'creative' | 'spiritual'
  sort_order?: number;
  usage_count?: number;
  rating?: number;
  created_at?: string;
  updated_at?: string;
  deep_memory_only?: boolean;
}

interface PromptsProps {
  prompts: Prompt[];
  selectedPrompt: Prompt | null;
  onPromptSelect: (prompt: Prompt) => void;
  onPromptStatusChange: (promptId: number, newStatus: boolean) => void;
  onSetActivePersonality: (promptKey: string, disableBase?: boolean) => Promise<void>;
  disableBasePersonality: boolean;
  onDisableBasePersonalityChange: (checked: boolean) => void;
}

const Prompts: React.FC<PromptsProps> = ({ 
  prompts: initialPrompts, 
  selectedPrompt, 
  onPromptSelect, 
  onPromptStatusChange, 
  onSetActivePersonality,
  disableBasePersonality,
  onDisableBasePersonalityChange
}) => {
  // Убираем локальное состояние - используем только глобальное из App.tsx
  const [modalPrompt, setModalPrompt] = useState<Prompt | null>(null);
  const [isModalVisible, setIsModalVisible] = useState(false);
  const [pipeline, setPipeline] = useState<any | null>(null);
  const [pipelineError, setPipelineError] = useState<string | null>(null);

  // Определяем платформу для правильных стилей
  const isTelegramMiniApp = window.Telegram?.WebApp?.initData || 
                           window.location.hostname.includes('test.soulpulse');

  // УДАЛЕНО: Хардкод определения темы - используем CSS переменные

  // Функция для получения правильных стилей модального контейнера
  const getModalContainerStyles = () => ({
    padding: 'var(--sp-spacing-md)',
    background: 'var(--sp-bg-card)',
    borderRadius: 'var(--sp-border-radius)',
    border: '1px solid var(--sp-border-primary)'
  });

  // Загружаем состояние отключения базовой личности из БД при изменении selectedPrompt
  useEffect(() => {
    if (selectedPrompt && selectedPrompt.key) {
      // Здесь нужно получить состояние из БД
      // Пока используем заглушку - в реальности нужно API для получения настроек
      console.log(`🔄 Загружаем состояние отключения базовой личности для ${selectedPrompt.name}`);
      // TODO: Добавить API вызов для получения настроек пользователя
    }
  }, [selectedPrompt]);

  // Загружаем конфигурацию пайплайна для функции chat (LLMFunctionConfig)
  useEffect(() => {
    const loadPipeline = async () => {
      try {
        setPipelineError(null);
        const resp = await fetch('/api/llm/functions', { headers: { 'Content-Type': 'application/json' } });
        if (!resp.ok) throw new Error(String(resp.status));
        const data = await resp.json();
        const chatFn = Array.isArray(data) ? data.find((f: any) => f.function_name === 'chat') : null;
        if (chatFn && chatFn.settings_json) {
          try {
            const parsed = JSON.parse(chatFn.settings_json);
            setPipeline(parsed);
          } catch {
            setPipeline({ raw: chatFn.settings_json });
          }
        } else {
          setPipeline(null);
        }
      } catch (e: any) {
        setPipelineError('Не удалось загрузить конфигурацию пайплайна чата');
      }
    };
    loadPipeline();
  }, []);

  const showPromptDetails = (prompt: Prompt) => {
    setModalPrompt(prompt);
    setIsModalVisible(true);
  };

  const handlePromptSelect = (prompt: Prompt) => {
    onPromptSelect(prompt);
    setIsModalVisible(false);
  };

  // Обработчик переключения активного состояния промпта
  const handleToggleActive = async (prompt: Prompt, checked: boolean) => {
    try {
      console.log(`🔄 Переключаем промпт ${prompt.name}: ${checked}`);
      console.log(`📋 Детали промпта:`, {
        id: prompt.id,
        key: prompt.key,
        name: prompt.name,
        current_is_active: prompt.is_active,
        new_state: checked
      });
      
      if (checked && prompt.key) {
        // Если включаем промпт, устанавливаем его как активную личность
        // При этом настройка disable_base_personality сбрасывается к False
        console.log(`🚀 Активируем промпт "${prompt.name}" с ключом "${prompt.key}"`);
        await onSetActivePersonality(prompt.key);
        console.log(`✅ Промпт "${prompt.name}" активирован`);
      } else {
        // Если выключаем промпт, активируем базовый "SoulPulse"
        console.log(`🔄 Деактивируем промпт "${prompt.name}", переключаем на базовый`);
        await onSetActivePersonality('prompt-4');
        console.log(`✅ Активирован базовый промпт "SoulPulse"`);
      }
    } catch (error) {
      console.error('❌ Ошибка при переключении промпта:', error);
      // В случае ошибки не обновляем состояние - оставляем как было
    }
  };

  // Обработчик изменения настройки "Отключить базовую личность"
  const handleDisableBaseChange = async (checked: boolean) => {
    console.log(`🔄 Изменяем настройку "Отключить базовую личность": ${checked}`);
    
    // Используем функцию из App.tsx, которая обрабатывает и API вызов, и обновление состояния
    await onDisableBasePersonalityChange(checked);
  };

  const renderPromptCard = (prompt: Prompt) => (
    <Card
      key={prompt.id}
      className={`prompt-card ${prompt.is_active ? 'active' : ''} ${prompt.is_base ? 'premium' : ''}`}
      styles={{ body: { padding: 0 } }}
      style={{ 
        // Прокидываем акцент из цвета промпта в CSS переменную
        ['--card-accent' as any]: prompt.icon_color || '#6d5efc'
      }}
    >
      <div className="prompt-content" style={{ padding: '8px 12px' }}>
        <div className="prompt-info">
          <div className="prompt-header">
            <Avatar 
              size={40}
              className="prompt-avatar"
              style={{ 
                backgroundColor: prompt.icon_color || '#6366f1'
              }}
            >
              {prompt.icon_emoji ? (
                <span style={{ fontSize: 'var(--sp-font-size-lg)' }}>{prompt.icon_emoji}</span>
              ) : (
                <FileTextOutlined style={{ fontSize: 'var(--sp-font-size-lg)' }} />
              )}
            </Avatar>
            <div className="prompt-title-section">
              <Title level={4} className="prompt-title">
                {prompt.name}
              </Title>
              <div className="prompt-tags">
                <Tag 
                  color={prompt.is_active ? 'success' : 'default'}
                  style={{ margin: 0, fontSize: 'var(--sp-font-size-xs)', padding: '0 var(--sp-spacing-xs)', height: '22px' }}
                >
                  {prompt.is_active ? 'Активен' : 'Неактивен'}
                </Tag>
                {prompt.is_base && (
                  <Tag 
                    color="blue"
                    style={{ margin: 0, fontSize: 'var(--sp-font-size-xs)', padding: '0 var(--sp-spacing-xs)', height: '22px' }}
                  >
                    Базовый
                  </Tag>
                )}
                {prompt.can_work_alone && (
                  <Tag color="orange" style={{ margin: 0, fontSize: 'var(--sp-font-size-xs)', padding: '0 var(--sp-spacing-xs)', height: '22px' }}>
                    Самостоятельный
                  </Tag>
                )}
                <Tag 
                  color="purple"
                  style={{ margin: 0, fontSize: 'var(--sp-font-size-xs)', padding: '0 var(--sp-spacing-xs)', height: '22px' }}
                >
                  {prompt.category}
                </Tag>
              </div>
            </div>
          </div>
          
          <Paragraph 
            style={{ 
              margin: '4px 0 6px 0',
              color: 'var(--sp-text-secondary)',
              fontSize: '13px',
              lineHeight: '1.2',
              display: '-webkit-box',
              WebkitLineClamp: 2,
              WebkitBoxOrient: 'vertical',
              overflow: 'hidden'
            }}
          >
            {prompt.description}
          </Paragraph>

                     <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginTop: '6px' }}>
             <Space size="small">
               {prompt.usage_count && (
                 <Tooltip title="Количество использований">
                   <Badge 
                     count={prompt.usage_count} 
                     size="small"
                     style={{ 
                       backgroundColor: 'var(--sp-text-secondary)',
                       color: 'var(--sp-bg-card)'
                     }}
                   />
                 </Tooltip>
               )}
               {prompt.rating && (
                 <Tooltip title="Рейтинг">
                   <Space size="small">
                     <StarOutlined style={{ color: 'var(--sp-color-warning)', fontSize: 'var(--sp-font-size-sm)' }} />
                     <Text style={{ fontSize: '12px', color: 'var(--sp-text-secondary)' }}>
                       {prompt.rating}
                     </Text>
                   </Space>
                 </Tooltip>
               )}
             </Space>

             <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
               <Switch
                 checked={prompt.is_active || false}
                 onChange={(checked) => {
                   console.log(`🔄 Switch clicked for ${prompt.name}: checked=${checked}, current is_active=${prompt.is_active}`);
                   handleToggleActive(prompt, checked);
                 }}
                 size="small"
                 onClick={(e: any) => {
                   console.log(`🖱️ Switch clicked for ${prompt.name}`);
                   if (e && e.stopPropagation) {
                     e.stopPropagation();
                   }
                 }}
               />
               <Button
                 type="text"
                 size="small"
                 icon={<InfoCircleOutlined style={{ fontSize: '18px', color: '#1890ff' }} />}
                 onClick={(e) => {
                   e.stopPropagation();
                   showPromptDetails(prompt);
                 }}
                 style={{ 
                   padding: '4px 8px',
                   minWidth: '28px',
                   minHeight: '28px',
                   display: 'flex',
                   alignItems: 'center',
                   justifyContent: 'center'
                 }}
               />
             </div>
           </div>
        </div>
      </div>
    </Card>
  );

  return (
    <div className="container prompts-page">
      {/* Заголовок */}
      <div className="soulpulse-header">
        <Title className="soulpulse-title">
          <img src="/android-chrome-192x192.png?v=2" alt="SoulPulse" style={{ width: 22, height: 22, borderRadius: 4, marginRight: 'var(--sp-spacing-md)' }} />
          Личности
        </Title>
        <Text className="soulpulse-subtitle">
          Выберите AI-личность для общения
        </Text>
      </div>

      {/* Минимальный отступ до контента */}
      <div style={{ marginBottom: 'var(--sp-spacing-xs)' }} />

      {/* Подсказка по работе личности и пайплайну чата */}
      <Alert
        type="info"
        message="Пояснение"
        description={
          <div>
            <div>Активная личность определяет стиль и память. Параметры пайплайна чата (резерв токенов, единый анализ, напоминания) влияют на формирование контекста.</div>
          </div>
        }
        showIcon
        style={{ marginBottom: 12 }}
      />

      {/* Превью конфигурации пайплайна чата */}
      <Card size="small" title="Pipeline чата (LLMFunctionConfig: chat)" style={{ marginBottom: 16 }}>
        {pipelineError && <Alert type="warning" message={pipelineError} showIcon style={{ marginBottom: 8 }} />}
        {pipeline ? (
          <div style={{ display: 'flex', gap: 24, flexWrap: 'wrap' }}>
            {'reserved_tokens' in pipeline && (
              <div><Text strong>reserved_tokens:</Text> <Text code>{String(pipeline.reserved_tokens)}</Text></div>
            )}
            {'include_unified_analysis' in pipeline && (
              <div><Text strong>include_unified_analysis:</Text> <Tag color={pipeline.include_unified_analysis ? 'green' : 'default'}>{String(pipeline.include_unified_analysis)}</Tag></div>
            )}
            {'include_reminders' in pipeline && (
              <div><Text strong>include_reminders:</Text> <Tag color={pipeline.include_reminders ? 'blue' : 'default'}>{String(pipeline.include_reminders)}</Tag></div>
            )}
            {'raw' in pipeline && (
              <div><Text strong>raw settings_json:</Text> <Text code>{pipeline.raw}</Text></div>
            )}
          </div>
        ) : (
          <Text type="secondary">Нет настроек для функции chat</Text>
        )}
        <div style={{ marginTop: 8 }}>
          <Button size="small" onClick={() => window.location.replace('/llm-settings')}>Открыть настройки LLM</Button>
        </div>
      </Card>

      {/* Список всех промптов для выбора */}
      <div>
        {initialPrompts.length > 0 ? (
          <div className="prompts-grid">
            {initialPrompts.map(prompt => renderPromptCard(prompt))}
          </div>
        ) : (
          <Card style={{ textAlign: 'center', padding: '40px 20px' }}>
            <FileTextOutlined style={{ fontSize: '48px', marginBottom: '16px', color: 'var(--sp-text-tertiary)' }} />
            <Text style={{ fontSize: '16px', color: 'var(--sp-text-secondary)' }}>
              Нет доступных промптов
            </Text>
            <br />
            <Text style={{ fontSize: '14px', color: 'var(--sp-text-tertiary)' }}>
              Личности загружаются из базы данных
            </Text>
          </Card>
        )}
      </div>

      {/* Модальное окно с деталями промпта */}
      <Modal
        title={
          <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
            <Avatar 
              size={32}
              style={{ 
                backgroundColor: modalPrompt?.icon_color || '#6366f1'
              }}
            >
              {modalPrompt?.icon_emoji ? (
                <span style={{ fontSize: '20px' }}>{modalPrompt.icon_emoji}</span>
              ) : (
                <FileTextOutlined />
              )}
            </Avatar>
            <span style={{ 
              color: isTelegramMiniApp ? 'var(--sp-text-primary)' : 'var(--text-primary)'
            }}>
              {modalPrompt?.name}
            </span>
          </div>
        }
        open={isModalVisible}
        onCancel={() => setIsModalVisible(false)}
        footer={[
          <Button key="cancel" onClick={() => setIsModalVisible(false)}>
            Закрыть
          </Button>,
          modalPrompt && (
            <Button 
              key="select" 
              type="primary"
              onClick={() => handlePromptSelect(modalPrompt)}
              disabled={modalPrompt.is_active}
            >
              {modalPrompt.is_active ? 'Уже активен' : 'Использовать промпт'}
            </Button>
          )
        ]}
        width={700}
        style={{ 
          top: 20
        }}
        className={isTelegramMiniApp ? 'telegram-mini-app-modal' : 'web-modal'}
      >
        {modalPrompt && (
          <div style={{ padding: '16px 0' }}>
            <div style={{ marginBottom: '20px' }}>
              {/* Основная информация */}
              <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '16px' }}>
                <Tag color="purple" style={{ margin: 0 }}>
                  {modalPrompt.category}
                </Tag>
                {modalPrompt.is_base && (
                  <Tag color="blue" style={{ margin: 0 }}>
                    Базовый
                  </Tag>
                )}
                <Tag color={modalPrompt.is_active ? 'success' : 'default'} style={{ margin: 0 }}>
                  {modalPrompt.is_active ? 'Активен' : 'Неактивен'}
                </Tag>
                {modalPrompt.kind && (
                  <Tag color="orange" style={{ margin: 0 }}>
                    {modalPrompt.kind}
                  </Tag>
                )}
              </div>
              
              {/* Описание */}
              <Paragraph style={{ fontSize: '16px', lineHeight: '1.6', marginBottom: '16px' }}>
                {modalPrompt.description}
              </Paragraph>

              {/* Функции */}
              {modalPrompt.features && modalPrompt.features.trim() !== '' && (
                <div style={{ marginBottom: '16px' }}>
                  <Text strong style={{ fontSize: '14px', color: 'var(--text-primary)' }}>
                    Функции:
                  </Text>
                  <div style={{ marginTop: '8px' }}>
                    {(() => {
                      try {
                        const features = JSON.parse(modalPrompt.features);
                        if (Array.isArray(features) && features.length > 0) {
                          return features.map((feature, index) => (
                            <Tag key={index} color="blue" style={{ margin: '4px', fontSize: '12px' }}>
                              {feature}
                            </Tag>
                          ));
                        }
                      } catch (e) {
                        // Если не JSON, показываем как текст
                        return <Text style={{ fontSize: '13px', color: 'var(--sp-text-secondary)' }}>
                          {modalPrompt.features}
                        </Text>;
                      }
                      return null;
                    })()}
                  </div>
                </div>
              )}

              {/* Целевая аудитория */}
              {modalPrompt.target_audience && modalPrompt.target_audience.trim() !== '' && (
                <div style={{ marginBottom: '16px' }}>
                  <Text strong style={{ fontSize: '14px', color: 'var(--text-primary)' }}>
                    Целевая аудитория:
                  </Text>
                  <Text style={{ fontSize: '13px', color: 'var(--sp-text-secondary)', display: 'block', marginTop: '8px' }}>
                    {modalPrompt.target_audience}
                  </Text>
                </div>
              )}

              {/* Триггеры активации */}
              {modalPrompt.activation_triggers && modalPrompt.activation_triggers.trim() !== '' && (
                <div style={{ marginBottom: '16px' }}>
                  <Text strong style={{ fontSize: '14px', color: 'var(--text-primary)' }}>
                    Активация:
                  </Text>
                  <div style={{ marginTop: '8px' }}>
                    {(() => {
                      try {
                        const triggers = JSON.parse(modalPrompt.activation_triggers);
                        if (Array.isArray(triggers) && triggers.length > 0) {
                          return triggers.map((trigger, index) => (
                            <Tag key={index} color="green" style={{ margin: '4px', fontSize: '12px' }}>
                              {trigger}
                            </Tag>
                          ));
                        }
                      } catch (e) {
                        // Если не JSON, показываем как текст
                        return <Text style={{ fontSize: '13px', color: 'var(--sp-text-secondary)' }}>
                          {modalPrompt.activation_triggers}
                        </Text>;
                      }
                      return null;
                    })()}
                  </div>
                </div>
              )}

              <Divider style={{ margin: '16px 0' }} />

              {/* Техническая информация (расширено по TECH_DESCRIPTIONS_v1.md) */}
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px' }}>
                {modalPrompt.key && (
                  <div>
                    <Text strong>Ключ:</Text>
                    <br />
                    <Text style={{ fontSize: '12px', fontFamily: 'monospace' }}>{modalPrompt.key}</Text>
                  </div>
                )}
                {modalPrompt.kind && (
                  <div>
                    <Text strong>Тип:</Text>
                    <br />
                    <Text>{modalPrompt.kind}</Text>
                  </div>
                )}
                {modalPrompt.locale && (
                  <div>
                    <Text strong>Локаль:</Text>
                    <br />
                    <Text>{modalPrompt.locale}</Text>
                  </div>
                )}
                {modalPrompt.category && (
                  <div>
                    <Text strong>Категория:</Text>
                    <br />
                    <Text>{modalPrompt.category}</Text>
                  </div>
                )}
                {modalPrompt.usage_count && (
                  <div>
                    <Text strong>Использований:</Text>
                    <br />
                    <Text>{modalPrompt.usage_count}</Text>
                  </div>
                )}
                {modalPrompt.rating && (
                  <div>
                    <Text strong>Рейтинг:</Text>
                    <br />
                    <Space>
                      <StarOutlined style={{ color: 'var(--sp-color-warning)' }} />
                      <Text>{modalPrompt.rating}</Text>
                    </Space>
                  </div>
                )}
                {modalPrompt.created_at && (
                  <div>
                    <Text strong>Создан:</Text>
                    <br />
                    <Text>{new Date(modalPrompt.created_at).toLocaleDateString('ru-RU')}</Text>
                  </div>
                )}
                {modalPrompt.updated_at && (
                  <div>
                    <Text strong>Обновлен:</Text>
                    <br />
                    <Text>{new Date(modalPrompt.updated_at).toLocaleDateString('ru-RU')}</Text>
                  </div>
                )}
                {modalPrompt.memory_algorithm && (
                  <div style={{ gridColumn: '1 / -1' }}>
                    <Text strong>Алгоритм памяти:</Text>
                    <br />
                    <Text style={{ fontSize: '12px', fontFamily: 'monospace' }}>{modalPrompt.memory_algorithm}</Text>
                  </div>
                )}
              </div>
            </div>

                         {/* Переключатель активации для всех промптов */}
                         <div style={getModalContainerStyles()}>
                           <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '12px' }}>
                             <Switch
                               checked={initialPrompts.find(p => p.key === modalPrompt.key)?.is_active || false}
                               onChange={async (checked) => {
                                 try {
                                   if (checked && modalPrompt.key) {
                                     await onSetActivePersonality(modalPrompt.key);
                                     console.log(`✅ Промпт "${modalPrompt.name}" активирован`);
                                   } else {
                                     await onSetActivePersonality('prompt-4');
                                     console.log(`✅ Активирован базовый промпт "SoulPulse"`);
                                   }
                                 } catch (error) {
                                   console.error('Ошибка при изменении статуса промпта:', error);
                                 }
                               }}
                             />
                             <Text strong>Активировать промпт</Text>
                           </div>
                           <Text style={{ fontSize: '14px', color: 'var(--sp-text-secondary)' }}>
                             Активированный промпт будет использоваться при общении с AI
                           </Text>
                         </div>

             {/* Настройка отключения базовой личности */}
             {modalPrompt.key !== 'prompt-4' && (
               <div style={{
                 ...getModalContainerStyles(),
                 marginTop: '16px'
               }}>
                 <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '12px' }}>
                   <Switch
                     checked={disableBasePersonality}
                     onChange={async (checked) => {
                       onDisableBasePersonalityChange(checked);
                       console.log(`🔄 Отключение базовой личности: ${checked}`);
                       
                       // Синхронизируем с БД
                       if (selectedPrompt && selectedPrompt.key) {
                         try {
                           console.log(`💾 Синхронизируем отключение базовой личности с БД...`);
                           await onSetActivePersonality(selectedPrompt.key, checked);
                           console.log(`✅ Отключение базовой личности синхронизировано с БД`);
                         } catch (error) {
                           console.error('❌ Ошибка синхронизации с БД:', error);
                           // Откатываем состояние в случае ошибки
                           onDisableBasePersonalityChange(!checked);
                         }
                       }
                     }}
                   />
                   <Text strong>Отключить базовую личность</Text>
                 </div>
                 <Text style={{ fontSize: '14px', color: 'var(--sp-text-secondary)' }}>
                   {modalPrompt.can_work_alone 
                     ? 'Этот промпт может работать самостоятельно. При отключении базовой личности будет использоваться только выбранная личность без "SoulPulse".'
                     : 'Этот промпт предназначен для работы с базовой личностью. Принудительное отключение может снизить качество ответов.'}
                 </Text>
               </div>
             )}

              {/* Настройка: Только глубинная память */}
              {modalPrompt.key && (
                <div style={{
                  ...getModalContainerStyles(),
                  marginTop: '16px'
                }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '8px' }}>
                    <Switch
                      checked={initialPrompts.find(p => p.key === modalPrompt.key)?.deep_memory_only || false}
                      onChange={async (checked) => {
                        try {
                          const tgId = sessionStorage.getItem('tg_id');
                          if (!tgId) throw new Error('Unauthorized');
                          const formData = new FormData();
                          formData.append('deep_memory_only', String(checked));
                          const resp = await fetch('/api/miniapp/prompts/update-settings', {
                            method: 'POST',
                            body: formData,
                            headers: { 'X-Telegram-User-ID': String(tgId) }
                          });
                          if (!resp.ok) throw new Error(String(resp.status));
                          console.log('✅ deep_memory_only сохранён');
                        } catch (e) {
                          console.error('❌ Ошибка сохранения deep_memory_only', e);
                        }
                      }}
                    />
                    <Text strong>Только глубинная память</Text>
                  </div>
                  <Text style={{ fontSize: '14px', color: 'var(--sp-text-secondary)' }}>
                    Недавняя история учитывается только после активации текущей личности; остальной контекст подбирается по ключевым словам/эмоциям/датам.
                  </Text>
                </div>
              )}
          </div>
        )}
      </Modal>
    </div>
  );
};

export default Prompts;
